window.docContents[92].resolve({"/#Hoare-Logic":{"contents":"\n\n\n\n\n\n\n\n\n\n\n\n","context":"","header":"Hoare Logic","id":"/#Hoare-Logic"},"/Preface/#Hoare-Logic--Preface--Practicalities":{"contents":"This volume assumes you already have Lean and VS Code set up as described in\nthe Logical Foundations Preface, and that you are comfortable with the basic\nmechanics of working through an SFL chapter. The exercises here have the\nsame \"advanced\"/\"optional\" markings, and star ratings.\n\nBriefly (see the Logical Foundations Preface for detail), to get started:\n\nIf you are using this book as part of a class, your instructor will have\ncreated a \"student\" release for you; download and unzip it, open the\nresulting directory in VS Code, and open a .lean file (e.g., HL/Slang.lean)\nto get started.\n\nIf you are reading on your own, clone the\nSF-in-Lean repository and run make\nhl-student from the root directory to build the student version of this\nvolume; it is written to _out/hl/student/, with an html/ directory and a\nlean/ directory, exactly as described for Logical Foundations. Run make\nstudent instead if you want all three volumes built together.\n\n\n\n\n\n","context":"Hoare Logic\u0009Preface","header":"1.3. Practicalities","id":"/Preface/#Hoare-Logic--Preface--Practicalities"}});